CREATE OR REPLACE FUNCTION public.order_verify_lookup(_order_id TEXT, _contact TEXT, _password TEXT)
RETURNS TABLE (ok BOOLEAN, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  o RECORD;
BEGIN
  SELECT * INTO o FROM public.orders WHERE id = _order_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, '订单号或查询密码不正确';
    RETURN;
  END IF;
  IF o.lookup_locked_until IS NOT NULL AND o.lookup_locked_until > NOW() THEN
    RETURN QUERY SELECT false, '尝试次数过多，请稍后再试';
    RETURN;
  END IF;
  IF _contact IS NOT NULL AND btrim(_contact) <> '' THEN
    IF lower(coalesce(o.contact_email, '')) <> lower(btrim(_contact))
       AND coalesce(o.contact_phone, '') <> btrim(_contact) THEN
      UPDATE public.orders SET lookup_fail_count = lookup_fail_count + 1,
        lookup_locked_until = CASE WHEN lookup_fail_count + 1 >= 5 THEN NOW() + INTERVAL '10 minutes' ELSE lookup_locked_until END
        WHERE id = _order_id;
      RETURN QUERY SELECT false, '订单号或查询密码不正确';
      RETURN;
    END IF;
  END IF;
  IF o.lookup_password_hash IS NULL OR
     coalesce(crypt(coalesce(_password, ''), o.lookup_password_hash) = o.lookup_password_hash, false) = false THEN
    UPDATE public.orders SET lookup_fail_count = lookup_fail_count + 1,
      lookup_locked_until = CASE WHEN lookup_fail_count + 1 >= 5 THEN NOW() + INTERVAL '10 minutes' ELSE lookup_locked_until END
      WHERE id = _order_id;
    RETURN QUERY SELECT false, '订单号或查询密码不正确';
    RETURN;
  END IF;
  UPDATE public.orders SET lookup_fail_count = 0, lookup_locked_until = NULL WHERE id = _order_id;
  RETURN QUERY SELECT true, NULL::TEXT;
END;
$$;

CREATE OR REPLACE FUNCTION public.order_confirm_payment(_order_id TEXT)
RETURNS TABLE (ok BOOLEAN, message TEXT)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  o RECORD;
  cs RECORD;
  new_timeline JSONB;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RETURN QUERY SELECT false, '无权限执行该操作';
    RETURN;
  END IF;
  SELECT * INTO o FROM public.orders WHERE id = _order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT false, '订单不存在'; RETURN; END IF;
  IF o.status NOT IN ('pending_payment', 'paid_pending_delivery') THEN
    RETURN QUERY SELECT false, '当前状态不可确认收款'; RETURN;
  END IF;
  IF o.status = 'pending_payment' THEN
    new_timeline := o.timeline || jsonb_build_object('at', now(), 'label', '已确认收款');
    UPDATE public.orders SET status = 'paid_pending_delivery', payment_ref = coalesce(payment_ref, '后台确认'),
      timeline = new_timeline, updated_at = NOW() WHERE id = _order_id;
  END IF;

  SELECT * INTO cs FROM public.card_secrets
    WHERE product_id = o.product_id AND status = 'unused' ORDER BY created_at ASC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT true, '已确认收款，但该商品暂无可用卡密，请导入后手动发货';
    RETURN;
  END IF;
  UPDATE public.card_secrets SET status = 'used', order_id = _order_id, used_at = NOW() WHERE id = cs.id;
  new_timeline := (SELECT timeline FROM public.orders WHERE id = _order_id) || jsonb_build_object('at', now(), 'label', '自动发货完成');
  UPDATE public.orders SET status = 'completed', card_secret = cs.code, timeline = new_timeline, updated_at = NOW()
    WHERE id = _order_id;
  RETURN QUERY SELECT true, '已确认收款并完成自动发货';
END;
$$;

