CREATE OR REPLACE FUNCTION public.coupon_try(_code TEXT, _amount NUMERIC, _user_id UUID)
RETURNS TABLE (ok BOOLEAN, discount NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  c RECORD;
  used_by_user INT;
BEGIN
  SELECT * INTO c FROM public.coupons WHERE upper(code) = upper(btrim(coalesce(_code, '')));
  IF NOT FOUND THEN RETURN QUERY SELECT false, 0, '优惠码不存在'; RETURN; END IF;
  IF c.is_active = false THEN RETURN QUERY SELECT false, 0, '优惠码已停用'; RETURN; END IF;
  IF c.expires_at IS NOT NULL AND c.expires_at < NOW() THEN RETURN QUERY SELECT false, 0, '优惠码已过期'; RETURN; END IF;
  IF c.used_count >= c.max_uses THEN RETURN QUERY SELECT false, 0, '优惠码已被领完'; RETURN; END IF;
  IF _amount < c.min_amount THEN RETURN QUERY SELECT false, 0, '订单金额未达到使用门槛'; RETURN; END IF;
  IF _user_id IS NOT NULL THEN
    SELECT count(*) INTO used_by_user FROM public.orders
      WHERE coupon_code = c.code AND (user_id = _user_id OR (user_id IS NULL AND _user_id IS NULL));
    IF used_by_user >= c.per_user_limit THEN RETURN QUERY SELECT false, 0, '该优惠码每人限用次数已达上限'; RETURN; END IF;
  END IF;
  IF c.type = 'percent' THEN
    RETURN QUERY SELECT true, round(_amount * c.value / 100, 2), NULL::TEXT;
  ELSE
    RETURN QUERY SELECT true, LEAST(c.value, _amount), NULL::TEXT;
  END IF;
END;
$$;

